#define assert(x) ((void)0)
#define NSL_INVALID_ID 0

typedef unsigned int nslSourceId;
typedef unsigned int nslSoundId;

enum EVENT
{
	EVT_SCORING_SERIES_END = 6
};

class ScoringManager
{
public:
	class Series;

	struct SeriesNode
	{
		SeriesNode * next;
		SeriesNode * prev;
		Series * value(void) { return (Series *) (this + 1); }
	};

	class SeriesList
	{
		SeriesNode * node;
	public:
		bool empty(void) const { return node->next == node; }
		Series & back(void) { return *node->prev->value(); }
	};

	class Series
	{
		char tricks[8];
	public:
		int numSpins;
		void GetPartialRawScores(int & facePoints, int & airPoints, int & tubePoints) const;
		float GetTubeTime(void) const;
	};

	class Chain
	{
		void * levelTricks;
		float multAdder;
	public:
		SeriesList series;
	};

private:
	char prefix[8];
	Chain chain;

public:
	const Chain & GetChain(void) const { return chain; }
};

class kellyslater_controller
{
	char prefix[4772];
	ScoringManager my_scoreManager;
public:
	ScoringManager & get_my_scoreManager(void) { return my_scoreManager; }
};

extern nslSourceId nslLoadSource(const char * sourceName);
extern nslSoundId nslAddSound(nslSourceId source);
extern void nslPlaySound(nslSoundId sound);

class IconChallenge
{
public:
	class Icon;
	class Task
	{
	public:
		enum TYPE
		{
			TYPE_AIR_FLIP,
			TYPE_AIR_GRAB,
			TYPE_AIR_SPIN,
			TYPE_AIR_POINTS_1000,
			TYPE_AIR_POINTS_2000,
			TYPE_AIR_POINTS_5000,
			TYPE_AIR_SPECIAL,
			TYPE_FACE_SPIN,
			TYPE_TUBE_TIME_10,
			TYPE_TUBE_TIME_15,
			TYPE_TUBE_TIME_30,
			TYPE_TUBE_TRICK,
			TYPE_NUM,
			TYPE_NONE
		};

	private:
		Icon * icon;
		bool completed;
		TYPE type;
		bool watchChain;

	public:
		void Despawn(void);
		void OnEvent(const EVENT event, kellyslater_controller * ksctrl, const int param2 = 0);
	};
};

void IconChallenge::Task::OnEvent(const EVENT event, kellyslater_controller * ksctrl, const int param2)
{
	const ScoringManager::Chain *				chain;
	const ScoringManager::Series *				series;
	int										seriesFacePoints = 0;
	int										seriesAirPoints = 0;
	int										seriesTubePoints = 0;
	bool									gotIt = false;

	// Get pointers to scoring chain and the last series in the chain.
	if (!ksctrl) return;
	chain = &(ksctrl->get_my_scoreManager().GetChain());
	if (!chain) return;
	if (chain->series.empty()) return;
	series = &(chain->series.back());
	if (!series) return;

	series->GetPartialRawScores(seriesFacePoints, seriesAirPoints, seriesTubePoints);

	// Process series end event.
	if (event == EVT_SCORING_SERIES_END && watchChain)
	{
		switch (type)
		{
		// Air tricks: a successful landing is all that's required.
		case TYPE_AIR_FLIP :
		case TYPE_AIR_GRAB :
			if (param2 == 1) gotIt = true;
			break;

		// Air points: series must be worth enough.
		case TYPE_AIR_POINTS_1000 :
			if (param2 == 1 && seriesAirPoints >= 1000) gotIt = true;
			break;
		case TYPE_AIR_POINTS_2000 :
			if (param2 == 1 && seriesAirPoints >= 2000) gotIt = true;
			break;
		case TYPE_AIR_POINTS_5000 :
			if (param2 == 1 && seriesAirPoints >= 5000) gotIt = true;
			break;

		// Air spins: series must have enough revolutions.
		case TYPE_AIR_SPIN :
			if (param2 == 1 && series->numSpins >= 2) gotIt = true;
			break;

		// Air special tricks: don't wipeout.
		case TYPE_AIR_SPECIAL :
			if (param2 == 1) gotIt = true;
			break;

		// Face spins: just don't wipeout.
		case TYPE_FACE_SPIN :
			if (param2 == 1) gotIt = true;
			break;

		// Tube time: series must have a ride entry with a long enough time.
		case TYPE_TUBE_TIME_10 :
			if (param2 == 1 && series->GetTubeTime() > 10.0f) gotIt = true;
			break;

		// Tube trick: don't wipeout.
		case TYPE_TUBE_TRICK :
			if (param2 == 1) gotIt = true;
			break;

		default : assert(0);
		};

		if (gotIt)
		{
			completed = true;
			Despawn();

			// Play sfx.
			nslSourceId src = NSL_INVALID_ID;
			nslSoundId snd = NSL_INVALID_ID;
			src = nslLoadSource("ICONDONE");
			if (src != NSL_INVALID_ID)
				snd = nslAddSound(src);
			if (snd != NSL_INVALID_ID)
				nslPlaySound(snd);
		}

		watchChain = false;
	}
}
